def tri_selection(T,N):
    for i in range(N-1):
        maxx=i
        for j in range(i+1,N):
            if (T[j]<T[maxx]):
                maxx=j
        if (maxx!=i):
            aux=T[i]
            T[i]=T[maxx]
            T[maxx]=aux
    return T

T=[5,2,52,31,20,6]
print(tri_selection(T,6))

